irule_mcp_policy.iRule:
# MCP identity-aware tool authorisation + per-identity rate limiting (LTM iRule, generated by Autopilot).
# Identity = Subject CN of the client certificate validated by the client-SSL profile (mTLS, authenticationMode require).
# Fail closed: unknown identity, unparseable/oversized/chunked bodies, unknown MCP methods, a tool name that cannot be
# identified unambiguously, and any tool not on the identity's allow-list are refused.
# Which part of the request is trusted depends on the DECLARED protocol (doc 34, finding B1):
#  * Mcp-Protocol-Version 2026-07-28: the MCP server rejects requests whose Mcp-Method/Mcp-Name headers disagree with
#    the body (-32020), so the headers identify the operation; Mcp-Method is mandatory.
#  * anything else (legacy 2025-xx sessions): the server IGNORES Mcp-Method/Mcp-Name, so those headers are never trusted
#    and method + tool are taken only from the JSON-RPC body (a decoy header cannot skip inspection).
when CLIENT_ACCEPTED { set ident "" }
when CLIENTSSL_CLIENTCERT {
  set ident ""
  if { [SSL::cert count] > 0 } { regexp {CN=([^,/]+)} [X509::subject [SSL::cert 0]] -> ident }
}
when HTTP_REQUEST {
  if { $ident eq "" } { HTTP::respond 401 content "client certificate required" ; return }
  set allowed {}
  switch -- $ident {
    "ap-validator" { set allowed {model_info score_transaction} }
    default {
      # Bounded, non-sensitive evidence: do not log certificate material, payloads, or credentials.
      set log_ident [string range $ident 0 63]
      regsub -all {[^A-Za-z0-9_.:-]} $log_ident _ log_ident
      log local0.notice "mcp-policy ts=[clock seconds] identity=$log_ident counter=not-counted branch=unknown_identity status=403"
      HTTP::respond 403 content "unknown agent identity" ; return
    }
  }
  # per-identity rate limit: 120 requests per calendar minute (fixed window; the key changes every minute,
  # so a busy identity is never locked out beyond the current minute)
  set key "$ident:[expr {[clock seconds] / 60}]"
  set n [table incr -subtable mcp_rate $key]
  if { $n == 1 } { table timeout -subtable mcp_rate $key 120 }
  if { $n > 120 } {
    set log_ident [string range $ident 0 63]
    regsub -all {[^A-Za-z0-9_.:-]} $log_ident _ log_ident
    log local0.notice "mcp-policy ts=[clock seconds] identity=$log_ident counter=$n branch=rate_limit status=429"
    HTTP::respond 429 content "rate limit exceeded" "Retry-After" "60" ; return
  }
  HTTP::header replace "X-Agent-Identity" $ident
  if { [HTTP::header value "Mcp-Protocol-Version"] eq "2026-07-28" } {
    set method [HTTP::header value "Mcp-Method"]
    if { [HTTP::method] eq "POST" } {
      switch -- $method {
        "server/discover" - "tools/list" - "ping" { }
        "tools/call" {
          set tool [HTTP::header value "Mcp-Name"]
          if { [lsearch -exact $allowed $tool] < 0 } {
            log local0.warn "mcp-policy deny ident=$ident tool=$tool"
            HTTP::respond 403 content "tool not permitted for $ident" ; return
          }
        }
        "" { HTTP::respond 400 content "Mcp-Method header required" ; return }
        default { log local0.warn "mcp-policy deny ident=$ident method=$method" ; HTTP::respond 403 content "MCP method not permitted" ; return }
      }
    }
  } elseif { [HTTP::method] eq "POST" } {
    # legacy (2025-xx) clients: method and tool only from the JSON-RPC body -> inspect it, or refuse
    set cl [HTTP::header value "Content-Length"]
    if { $cl eq "" || ![string is integer -strict $cl] } { HTTP::respond 411 content "Content-Length required for policy inspection" ; return }
    if { $cl > 65536 } { HTTP::respond 413 content "request too large for policy inspection" ; return }
    if { $cl > 0 } { HTTP::collect $cl } else { HTTP::respond 400 content "empty JSON-RPC request" ; return }
  }
}
when HTTP_REQUEST_DATA {
  set body [string trimleft [HTTP::payload]]
  if { [string match {\[*} $body] } { HTTP::respond 400 content "JSON-RPC batches are not permitted" ; return }
  set methods [regexp -all -inline {"method"\s*:\s*"([^"]*)"} $body]
  if { [llength $methods] != 2 } { HTTP::respond 400 content "exactly one JSON-RPC method required" ; return }
  set m [lindex $methods 1]
  switch -- $m {
    "initialize" - "notifications/initialized" - "notifications/cancelled" - "ping" - "tools/list" { }
    "tools/call" {
      # exactly one "name" key: with more (e.g. nested in arguments or _meta) the requested tool is ambiguous -> refuse
      set names [regexp -all -inline {"name"\s*:\s*"([^"]*)"} $body]
      if { [llength $names] != 2 } { HTTP::respond 400 content "tool cannot be identified unambiguously" ; return }
      set tool [lindex $names 1]
      if { [lsearch -exact $allowed $tool] < 0 } {
        log local0.warn "mcp-policy deny ident=$ident tool=$tool (legacy)"
        HTTP::respond 403 content "tool not permitted for $ident" ; return
      }
    }
    default { log local0.warn "mcp-policy deny ident=$ident method=$m (legacy)" ; HTTP::respond 403 content "MCP method not permitted" ; return }
  }
  HTTP::release
}
